"use client";

import React, { useEffect, useState } from "react";
import {
	Alert,
	Badge,
	Descriptions,
	Divider,
	Spin,
	Image,
	Button,
	Tooltip,
	Table,
	Card,
	Tabs,
	Flex,
	Space,
} from "antd";
import type { DescriptionsProps } from "antd";
import { DownloadOutlined } from "@ant-design/icons";

import api from "@/lib/axiosInstance";
import UserTag from "@/app/_components/UserTag";
import DateDisplay from "@/app/_components/DateDisplay";

interface IDesignImages {
	designBy: string;
	createdAt: Date;

	damageFront: string;
	damageSide: string;
	damageTop: string;
	damageBack: string;
	designFront: string;
	designSide: string;
	designTop: string;
	designBack: string;
	damageFrontWithSoftTissues: string;
	damageSideWithSoftTissues: string;
	designFrontWithSoftTissues: string;
	designSideWithSoftTissues: string;
	designWithDimensions: string;
}

interface IQCDocs {
	designBy: string;
	createdAt: Date;

	skullDefectSpecificationImage: string;
	skullDefectSpecificationA: number;
	skullDefectSpecificationB: number;
	skullDefectSpecificationC: number;

	implantModelSpecificationImage: string;
	implantModelSpecificationA: number;
	implantModelSpecificationB: number;
	implantModelSpecificationC: number;
}

interface IDesignFile {
	designBy: string;
	createdAt: Date;
	designFile: string;
}

interface IDesignApproval {
	isApproved: boolean;
	createdAt: Date;
	approvedBy: string;
	comment: string;
}

interface Design {
	designImages: IDesignImages;
	qcDocs: IQCDocs;
	designFile: IDesignFile;
	approval: IDesignApproval;
}

type Data = Design[];

const App: React.FC<{ orderId: string; onlyQCDocs: boolean }> = ({ orderId, onlyQCDocs = false }) => {
	const [data, setData] = useState<Data | null>(null);
	const [loading, setLoading] = useState<boolean>(true);
	const [columns, setColumns] = useState(2);

	useEffect(() => {
		function handleResize() {
			setColumns(window.innerWidth < 768 ? 1 : 2);
		}
		handleResize();
		window.addEventListener("resize", handleResize);
		return () => window.removeEventListener("resize", handleResize);
	}, []);

	useEffect(() => {
		const fetchData = async () => {
			try {
				const response = await api.get(`orders/${orderId}/designs`);
				setData(response.data);
			} catch (error) {
				console.error("Error fetching order data:", error);
			} finally {
				setLoading(false);
			}
		};

		fetchData();
	}, [orderId]);

	if (loading) return <Spin size="large" />;
	if (!data || data.length === 0) return <Alert message="No design details available." type="info" showIcon />;

	return (
		<>
			<Tabs defaultActiveKey="0">
				{data.map((section, index) => {
					const designItems: DescriptionsProps["items"] = [
						{
							key: "designBy",
							label: "Done By",
							children: section.designImages.designBy ? (
								<UserTag userId={section.designImages.designBy} />
							) : (
								"N/A"
							),
						},
						{
							key: "createdAt",
							label: "Date",
							children: section.designImages.createdAt ? (
								<DateDisplay isoDate={section.designImages.createdAt} />
							) : (
								"N/A"
							),
						},
					];

					const qcDocsItems: DescriptionsProps["items"] = [
						{
							key: "createdAt",
							label: "Design Date",
							children: section.qcDocs?.createdAt ? (
								<DateDisplay isoDate={section.qcDocs?.createdAt} />
							) : (
								"N/A"
							),
						},
						{
							key: "designBy",
							label: "Designed By",
							children: section.qcDocs?.designBy ? <UserTag userId={section.qcDocs?.designBy} /> : "N/A",
						},
					];

					const designFileItems: DescriptionsProps["items"] = [
						{
							key: "designFileUploadDate",
							label: "Uploaded Date",
							children: section.designFile?.createdAt ? (
								<DateDisplay isoDate={section.designFile?.createdAt} />
							) : (
								"N/A"
							),
						},
						{
							key: "approvedBy",
							label: "Uploaded By",
							children: section.designFile?.designBy ? (
								<UserTag userId={section.designFile?.designBy} />
							) : (
								"N/A"
							),
						},
					];

					const approvalItems: DescriptionsProps["items"] = [
						{
							key: "isApproved",
							label: "Approved",
							children: section.approval?.isApproved ? (
								<Badge count="Approved" style={{ backgroundColor: "#52c41a" }} />
							) : (
								<Badge count="Rejected" />
							),
						},
						{
							key: "createdAt",
							label: "Approval Date",
							children: section.approval?.createdAt ? (
								<DateDisplay isoDate={section.approval?.createdAt} />
							) : (
								"N/A"
							),
						},
						{
							key: "approvedBy",
							label: "Approved By",
							children: section.approval?.approvedBy ? (
								<UserTag userId={section.approval?.approvedBy} />
							) : (
								"N/A"
							),
						},
						{
							key: "comment",
							label: "Comment",
							children: section.approval?.comment ?? "N/A",
						},
					];

					if (onlyQCDocs)
						return (
							<Tabs.TabPane tab={`Design Attempt #${index + 1}`} key={index}>
								<Card>
									<Descriptions title="QC Docs" items={qcDocsItems} column={columns} />
									<Flex wrap gap={"large"} justify="space-around">
										<Card>
											<Image
												width={300}
												src={section.qcDocs?.implantModelSpecificationImage}
												alt="implantModelSpecificationImage"
												fallback="data:image/png;base64,"
												preview={{
													mask: "implantModelSpecificationImage",
												}}
											/>
											<br />
											<Table
												columns={[
													{
														title: "No",
														dataIndex: "no",
														key: "no",
														width: 100,
													},
													{
														title: "Parameter/Specification (mm)",
														dataIndex: "parameter",
														key: "parameter",
														width: 200,
														align: "center",
													},
												]}
												dataSource={[
													{
														key: "1",
														no: "A",
														parameter: section.qcDocs?.implantModelSpecificationA,
													},
													{
														key: "2",
														no: "B",
														parameter: section.qcDocs?.implantModelSpecificationB,
													},
													{
														key: "3",
														no: "C",
														parameter: section.qcDocs?.implantModelSpecificationC,
													},
												]}
												size="small"
												pagination={false}
											/>
										</Card>
										<Card>
											<Image
												width={300}
												src={section.qcDocs?.skullDefectSpecificationImage}
												alt="skullDefectSpecificationImage"
												fallback="data:image/png;base64,"
												preview={{
													mask: "skullDefectSpecificationImage",
												}}
											/>
											<Table
												columns={[
													{
														title: "No",
														dataIndex: "no",
														key: "no",
														width: 100,
													},
													{
														title: "Parameter/Specification (mm)",
														dataIndex: "parameter",
														key: "parameter",
														width: 200,
														align: "center",
													},
												]}
												dataSource={[
													{
														key: "1",
														no: "A",
														parameter: section.qcDocs?.skullDefectSpecificationA,
													},
													{
														key: "2",
														no: "B",
														parameter: section.qcDocs?.skullDefectSpecificationB,
													},
													{
														key: "3",
														no: "C",
														parameter: section.qcDocs?.skullDefectSpecificationC,
													},
												]}
												size="small"
												pagination={false}
											/>
										</Card>
									</Flex>
								</Card>
							</Tabs.TabPane>
						);
					else
						return (
							<Tabs.TabPane tab={`Design Attempt #${index + 1}`} key={index}>
								<Space direction="vertical" style={{ width: "100%", overflowX: "auto" }}>
									<Card>
										<Descriptions title="Design Details" items={designItems} column={columns} />
										<Divider />
										<Flex wrap justify="space-evenly">
											<Image.PreviewGroup fallback="data:image/png;base64,">
												<Image
													width={200}
													src={section.designImages.damageFront}
													alt="damageFront"
													preview={
														section.designImages.damageFront
															? {
																	visible: section.designImages.damageFront
																		? true
																		: false,
																	mask: "Damage Front",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.damageSide}
													alt=""
													preview={
														section.designImages.damageSide
															? {
																	mask: "Damage Side",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.damageTop}
													alt=""
													preview={
														section.designImages.damageTop
															? {
																	mask: "Damage Top",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.damageBack}
													alt=""
													preview={
														section.designImages.damageBack
															? {
																	mask: "Damage Back",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.designFront}
													alt=""
													preview={
														section.designImages.designFront
															? {
																	mask: "Design Front",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.designSide}
													alt=""
													preview={
														section.designImages.designSide
															? {
																	mask: "Design Side",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.designTop}
													alt=""
													preview={
														section.designImages.designTop
															? {
																	mask: "Design Top",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.designBack}
													alt=""
													preview={
														section.designImages.designBack
															? {
																	mask: "Design Back",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.damageFrontWithSoftTissues}
													alt=""
													preview={
														section.designImages.damageFrontWithSoftTissues
															? {
																	mask: "Damage FrontWithSoftTissues",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.damageSideWithSoftTissues}
													alt=""
													preview={
														section.designImages.damageSideWithSoftTissues
															? {
																	mask: "Damage SideWithSoftTissues",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.designFrontWithSoftTissues}
													alt=""
													preview={
														section.designImages.designFrontWithSoftTissues
															? {
																	mask: "Design FrontWithSoftTissues",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.designSideWithSoftTissues}
													alt=""
													preview={
														section.designImages.designSideWithSoftTissues
															? {
																	mask: "Design SideWithSoftTissues",
																}
															: false
													}
												/>
												<Image
													width={200}
													src={section.designImages.designWithDimensions}
													alt=""
													preview={
														section.designImages.designWithDimensions
															? {
																	mask: "Design WithDimensions",
																}
															: false
													}
												/>
											</Image.PreviewGroup>
										</Flex>
									</Card>
									<Card>
										<Descriptions title="QC Docs" items={qcDocsItems} column={columns} />
										<Flex wrap gap={"large"} justify="space-around">
											<Card>
												<Image
													// width={300}
													src={section.qcDocs?.implantModelSpecificationImage}
													alt="implantModelSpecificationImage"
													fallback="data:image/png;base64,"
													preview={{
														mask: "implantModelSpecificationImage",
													}}
												/>
												<br />
												<Table
													columns={[
														{
															title: "No",
															dataIndex: "no",
															key: "no",
															width: 100,
														},
														{
															title: "Parameter/Specification (mm)",
															dataIndex: "parameter",
															key: "parameter",
															width: 200,
															align: "center",
														},
													]}
													dataSource={[
														{
															key: "1",
															no: "A",
															parameter: section.qcDocs?.implantModelSpecificationA,
														},
														{
															key: "2",
															no: "B",
															parameter: section.qcDocs?.implantModelSpecificationB,
														},
														{
															key: "3",
															no: "C",
															parameter: section.qcDocs?.implantModelSpecificationC,
														},
													]}
													size="small"
													pagination={false}
												/>
											</Card>
											<Card>
												<Image
													// width={300}
													src={section.qcDocs?.skullDefectSpecificationImage}
													alt="skullDefectSpecificationImage"
													fallback="data:image/png;base64,"
													preview={{
														mask: "skullDefectSpecificationImage",
													}}
												/>
												<Table
													columns={[
														{
															title: "No",
															dataIndex: "no",
															key: "no",
															width: 100,
														},
														{
															title: "Parameter/Specification (mm)",
															dataIndex: "parameter",
															key: "parameter",
															width: 200,
															align: "center",
														},
													]}
													dataSource={[
														{
															key: "1",
															no: "A",
															parameter: section.qcDocs?.skullDefectSpecificationA,
														},
														{
															key: "2",
															no: "B",
															parameter: section.qcDocs?.skullDefectSpecificationB,
														},
														{
															key: "3",
															no: "C",
															parameter: section.qcDocs?.skullDefectSpecificationC,
														},
													]}
													size="small"
													pagination={false}
												/>
											</Card>
										</Flex>
									</Card>

									<Card>
										<Tooltip
											title={section.designFile?.designFile ? "" : "Design File not available"}
										>
											<Button
												icon={<DownloadOutlined />}
												href={section.designFile?.designFile}
												target="_blank"
												rel="noopener noreferrer"
												disabled={!section.designFile?.designFile}
											>
												Download Design
											</Button>
										</Tooltip>
										<Divider />
										<Descriptions items={designFileItems} column={columns} />
									</Card>

									<Card>
										{approvalItems[index] != null && (
											<Descriptions
												title="Approval Info"
												items={approvalItems}
												column={columns}
											/>
										)}
									</Card>
								</Space>
							</Tabs.TabPane>
						);
				})}
			</Tabs>
		</>
	);
};

export default App;
